import AppKit
import Combine
import Vision

/// Clipboard history with layered privacy controls:
/// 1. pasteboard markers (concealed / transient / auto-generated),
/// 2. a built-in password-manager blocklist plus user-excluded apps (frontmost app at copy time),
/// 3. pause (manual, or automatic in presentation mode),
/// 4. retention: item cap, optional expiry, memory-only history.
/// Only items the user explicitly pins (text) are written to disk.
/// None of this guarantees a secret is never captured; it reduces the chance.
@MainActor
final class ClipboardService: ObservableObject {
    enum Content {
        case text(String)
        case image(NSImage)
    }

    struct Item: Identifiable {
        let id: UUID
        let date: Date
        let content: Content
        var pinned: Bool
        let sourceApp: String?

        init(id: UUID = UUID(), date: Date = Date(), content: Content, pinned: Bool = false, sourceApp: String? = nil) {
            self.id = id
            self.date = date
            self.content = content
            self.pinned = pinned
            self.sourceApp = sourceApp
        }

        var isImage: Bool {
            if case .image = content { return true }
            return false
        }

        var text: String? {
            if case .text(let s) = content { return s }
            return nil
        }

        var preview: String {
            switch content {
            case .text(let s):
                return s.trimmingCharacters(in: .whitespacesAndNewlines)
                    .replacingOccurrences(of: "\n", with: " ")
            case .image(let img):
                return "Image \(Int(img.size.width))×\(Int(img.size.height))"
            }
        }

        var searchText: String { text ?? "image" }
    }

    @Published private(set) var items: [Item] = []

    /// Set by the coordinator while presentation mode is on.
    @Published var temporarilyPaused = false

    private let settings: AppSettings
    private let maxImages = 12
    private let maxTextLength = 200_000
    private var lastChangeCount = NSPasteboard.general.changeCount
    private var timer: Timer?
    private let pinnedKey = "pinnedClips"

    nonisolated static let ignoredTypes: Set<String> = [
        "org.nspasteboard.ConcealedType",
        "org.nspasteboard.TransientType",
        "org.nspasteboard.AutoGeneratedType",
        "com.agilebits.onepassword",
        "de.petermaurer.TransientPasteboardType",
        "Pasteboard generator type"
    ]

    nonisolated static let builtInExcludedApps: Set<String> = [
        "com.apple.keychainaccess",
        "com.apple.Passwords",
        "com.1password.1password",
        "com.agilebits.onepassword7",
        "com.bitwarden.desktop",
        "com.lastpass.LastPass",
        "com.dashlane.dashlanephonefinal",
        "org.keepassxc.keepassxc"
    ]

    init(settings: AppSettings = .shared) {
        self.settings = settings
        let pinned = AppDefaults.store.stringArray(forKey: pinnedKey) ?? []
        items = pinned.map { Item(content: .text($0), pinned: true) }
    }

    var isRecording: Bool { !settings.clipboardPaused && !temporarilyPaused }

    func start() {
        // NSPasteboard has no change notification; 0.5 s changeCount polling is the standard approach.
        let t = Timer(timeInterval: 0.5, repeats: true) { [weak self] _ in
            Task { @MainActor in self?.check() }
        }
        t.tolerance = 0.2
        RunLoop.main.add(t, forMode: .common)
        timer = t
    }

    /// Decides whether a pasteboard change may be recorded. Exposed for tests.
    nonisolated static func shouldRecord(types: Set<String>, frontmostBundleID: String?, userExcluded: [String]) -> Bool {
        guard types.isDisjoint(with: ignoredTypes) else { return false }
        if let bundle = frontmostBundleID {
            if builtInExcludedApps.contains(bundle) || userExcluded.contains(bundle) { return false }
        }
        return true
    }

    private func check() {
        expireOldItems()
        let pb = NSPasteboard.general
        guard pb.changeCount != lastChangeCount else { return }
        lastChangeCount = pb.changeCount
        guard isRecording else { return }

        let types = Set((pb.types ?? []).map(\.rawValue))
        let frontmost = NSWorkspace.shared.frontmostApplication?.bundleIdentifier
        guard Self.shouldRecord(types: types, frontmostBundleID: frontmost, userExcluded: settings.excludedApps) else { return }

        if let text = pb.string(forType: .string),
           text.utf16.count <= maxTextLength,
           !text.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
            insert(.text(text), sourceApp: frontmost)
        } else if types.contains(NSPasteboard.PasteboardType.png.rawValue)
                    || types.contains(NSPasteboard.PasteboardType.tiff.rawValue),
                  let image = NSImage(pasteboard: pb) {
            insert(.image(image), sourceApp: frontmost)
        }
    }

    private func insert(_ content: Content, sourceApp: String?) {
        var pinned = false
        if case .text(let s) = content {
            if let existing = items.first(where: { $0.text == s }) { pinned = existing.pinned }
            items.removeAll { $0.text == s }
        }
        items.insert(Item(content: content, pinned: pinned, sourceApp: sourceApp), at: 0)
        enforceLimits()
    }

    private func enforceLimits() {
        var imageCount = 0
        items = items.filter { item in
            guard item.isImage, !item.pinned else { return true }
            imageCount += 1
            return imageCount <= maxImages
        }
        let cap = max(10, settings.clipboardMaxItems)
        var unpinnedSeen = 0
        items = items.filter { item in
            guard !item.pinned else { return true }
            unpinnedSeen += 1
            return unpinnedSeen <= cap
        }
    }

    private func expireOldItems() {
        let hours = settings.clipboardExpiryHours
        guard hours > 0 else { return }
        let cutoff = Date().addingTimeInterval(-Double(hours) * 3600)
        if items.contains(where: { !$0.pinned && $0.date < cutoff }) {
            items.removeAll { !$0.pinned && $0.date < cutoff }
        }
    }

    /// Used only by the snapshot renderer to show sample content.
    func previewInsert(_ content: Content) {
        insert(content, sourceApp: nil)
    }

    // MARK: Actions

    func copy(_ item: Item) {
        let pb = NSPasteboard.general
        pb.clearContents()
        switch item.content {
        case .text(let s): pb.setString(s, forType: .string)
        case .image(let img): pb.writeObjects([img])
        }
        lastChangeCount = pb.changeCount
        if let i = items.firstIndex(where: { $0.id == item.id }) {
            let moved = items.remove(at: i)
            items.insert(Item(content: moved.content, pinned: moved.pinned, sourceApp: moved.sourceApp), at: 0)
        }
        A11y.announce("Copied")
    }

    func togglePin(_ item: Item) {
        guard item.text != nil, let i = items.firstIndex(where: { $0.id == item.id }) else { return }
        items[i].pinned.toggle()
        savePinned()
        A11y.announce(items[i].pinned ? "Pinned" : "Unpinned")
    }

    func remove(_ item: Item) {
        items.removeAll { $0.id == item.id }
        if item.pinned { savePinned() }
    }

    /// Clears history but keeps pinned items.
    func clear() {
        items.removeAll { !$0.pinned }
        A11y.announce("Clipboard history cleared")
    }

    func clearIncludingPinned() {
        items.removeAll()
        savePinned()
        A11y.announce("Clipboard history and pins cleared")
    }

    private func savePinned() {
        let pinned = items.filter(\.pinned).compactMap(\.text)
        AppDefaults.store.set(pinned, forKey: pinnedKey)
    }

    /// On-device text recognition, only when the user asks for it.
    func recognizeText(in item: Item, completion: @escaping @MainActor @Sendable (Bool) -> Void) {
        guard case .image(let image) = item.content,
              let cg = image.cgImage(forProposedRect: nil, context: nil, hints: nil) else {
            completion(false)
            return
        }
        DispatchQueue.global(qos: .userInitiated).async { [weak self] in
            let request = VNRecognizeTextRequest()
            request.recognitionLevel = .accurate
            request.usesLanguageCorrection = true
            let handler = VNImageRequestHandler(cgImage: cg, options: [:])
            try? handler.perform([request])
            let text = (request.results ?? [])
                .compactMap { $0.topCandidates(1).first?.string }
                .joined(separator: "\n")
            Task { @MainActor in
                guard let self else { return }
                guard !text.isEmpty else {
                    A11y.announce("No text found")
                    completion(false)
                    return
                }
                let pb = NSPasteboard.general
                pb.clearContents()
                pb.setString(text, forType: .string)
                self.lastChangeCount = pb.changeCount
                self.insert(.text(text), sourceApp: Bundle.main.bundleIdentifier)
                A11y.announce("Text copied")
                completion(true)
            }
        }
    }
}
